) AS (
  VALUES 
    (302::BIGINT, 'Para compu y sociedad sin duda llevelo con este profe, es la mejor opcion. Las clases son solo de conversar y debatir, en lo personal me gusto mucho y era un curso diferente que de verdad necesitaba en el semestre que lo lleve. Solo vaya con la mentalidad de que es un curso x, para charlar.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa']::TEXT[], '2026-08-14T00:00:00+00:00'::TIMESTAMPTZ, 'd719205c48451996f71a5b949842a14949d1aa4214de5e808f20ad35e44b9095'::TEXT, ARRAY[1156]::BIGINT[]),
    (302::BIGINT, 'No es el mejor explicando cuando lo hace, no es un curso sencillo como tal pero realmente dejé de entenderle como a medio semestre. Sin embargo, es buena persona, da buena retroalimentación y se nota que da clases porque le gusta. Hace quiz cada semana de por medio así que toca autodidacta.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2026-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'aa7d5aee89b48ee9d881e873a4319b9fbac31a77a88453dd5583f4723e9ff923'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Super sencillo pasar, buen profesor y realmente es como se debería dar un curso de estos, recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes']::TEXT[], '2025-12-03T00:00:00+00:00'::TIMESTAMPTZ, '35c5d81aaa1d6085cf975adfef9a8f7334f04ed2f31e4524d41cbc761c6f2cfb'::TEXT, ARRAY[1249, 1156]::BIGINT[]),
    (302::BIGINT, 'Excelente persona, un curso que lo que da es sueño lo hace una experiencia de crecimiento personal y critico sin hacer un curso pesado. Le toma mucha importancia a la opinion del estudiante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-20T00:00:00+00:00'::TIMESTAMPTZ, 'd16b0bc9776b08fe825d759cfd4648e3afd59ae888e52f7077642b23ccea6fd8'::TEXT, ARRAY[1156]::BIGINT[]),
    (302::BIGINT, 'NO HAGA CASO A LOS DEMÁS, este profe no explica nada, da ejemplos super sencillos y después al hacer los quizes y tareas son ejercicios bien difíciles, deja proyectos de cosas que ni se ven en clase y hay que buscar por todo lado como hacerlos, si quiere aprender no es con el, si quiere pasar use IA'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2025-07-31T00:00:00+00:00'::TIMESTAMPTZ, '05e7b423a44652bef0fbd423750e406c18d86b744da7b229a2deb899370c63ad'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Este curso es programar en C++, lo que ya de entrada es compliado. Pero la verdad el profe trata de ayudarle a uno, le da trabajos para reponer, deja prácticas para los quices que son muy similares y hasta tiene la opción de eximirse del exámen final. Supér recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, '04d6db952dd2d2cfcf59e3cacb47e289e47e05ed00b7322ed13f6ab0b4a183c1'::TEXT, ARRAY[1253]::BIGINT[]),
    (302::BIGINT, 'El profe tiene mucho conocimiento y le gusta mucho enseñar, sus explicaciones son claras y presisas.Da bastante tiempo para hacer las tareas y es muy organizado, tambien da varias oportunidades para tener puntos extras y es muy acesible para caercarse hablar con él del curso o otra cosa.Good profe'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2024-11-06T00:00:00+00:00'::TIMESTAMPTZ, '8dbbdbf2de65002d9f834ada090c0303d4938a784dbed73a513968ca008dbf5b'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'No haga caso a los demas comentarios, si usted no sabe programar este profesor es de los mejores, da una explicacion corta pero clara y si no entiende no le importa devolverse, es de los UNICOS profesores que SI quiere enseñar y eso le importa, pero preparese a que le diga que está perdido'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Asistencia obligatoria']::TEXT[], '2024-10-16T00:00:00+00:00'::TIMESTAMPTZ, 'b7dfffbd020146a6825d383da4ddba999ba9dba13797b44dd8e8f2c1cde55890'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'No tiene una calificación más baja solo porque regala pts extra cuando le da la gana. No se lo recomiendo porque le va a decir que usted tiene que buscar la solucion a sus propios problemas. Intente meter con Garro, explica mejor. Solo recomendable si va a ser autodidacta. No cometa el mismo error'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2024-09-04T00:00:00+00:00'::TIMESTAMPTZ, '7ed311e746fa2df9e7f273690bbe8d5382b8382921ecc3e29b60b6c2e5d8da9d'::TEXT, ARRAY[1253]::BIGINT[]),
    (302::BIGINT, 'Explicando no es el mejor, pero el curso en sí es complejo así que póngale, si usted estudia, investiga y le pone pasa sobrado. Da puntos extra en tareas y proyectos. Los proyectos son demasiado duros.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Pocos exámenes']::TEXT[], '2024-01-27T00:00:00+00:00'::TIMESTAMPTZ, '880022406ad4ed648f21ab22905de98a8adc78ba14704606d1d02b237e2ef28f'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Preparase para no aprender a programar en este curso, él no enseña, solo de da ejemplos de las funciones y luego pide trabajos para los cuales hay saber programar previamente, los proyectos son rídiculamente complejos para el nivel del curso, da puntos extra y como persona es ámeno'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2024-01-11T00:00:00+00:00'::TIMESTAMPTZ, '6b3254ab5b8a76d6bfd5bb3d7286743479a8f6a68d579c2482a20faca3f3b880'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Excelente profesor. Las clases son muy amenas y la verdad son livianas. Prioriza realmente el desarrollo de crear una postura crítica y argumental para el estudiante. Los trabajos son livianos. Realmente un excelente profesor y las clases son demasiado interesantes! Recomendado al mil'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '85f9edb4c31aabda9dea9c20346309a83d3e423d72dbab3bcb240a9306465a84'::TEXT, ARRAY[1156]::BIGINT[]),
    (302::BIGINT, 'Es súper buena gente, hay que ser muy autodidacta pero ayuda bastante, no enseña a programar en C++ sino a entender cómo funcionan las cosas, las clases son cortas. Intente eximirse en el examen.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '8e03fdccef6215b7cd5a0f0f24b784506a439eeb5e383b1e4dc9de558a5658e6'::TEXT, ARRAY[1253]::BIGINT[]),
    (302::BIGINT, 'Las clases son muy divertidas, si se disfruta mucho el tiempo en clase. Se interesa en conocer bien a sus estudiantes y ayudar con trabajos extra y actividades extra para ganar puntos. Eso sí, es mejor saber C++ antes de llevarlo porque NO se enseña ahí. Pero si hace todo y estudia si se pasa.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '2e310218b1c90cb6015bf4775262a6fd97be0d965884ca9ec284912685904f25'::TEXT, ARRAY[1253]::BIGINT[]),
    (302::BIGINT, 'Muy recomendado para el curso de compu y sociedad, las clases fuero super dinamicas y valiosas y una carga academica adecuada con las tareas/proyecto. Super buena persona y se ve que le interesa llevarse bien con los estudiantes'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '5c3c647201f5cd6f1e0856823c2693133e7ea5127e2beeada7077a61ff22c734'::TEXT, ARRAY[1156]::BIGINT[]),
    (302::BIGINT, 'Las clases son super cortas, a veces duran solo 30 mins, él NO enseña a programar ni aunque usted venga de Python a C++, solo da teoría, hay que ser totalmente autodidacta. Es muy buena persona e intenta ayudarlo a pasar regalando quices. Intente eximirse del examen final con ganar 80 en los quices.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo']::TEXT[], '2022-12-07T00:00:00+00:00'::TIMESTAMPTZ, '28df61bb5eb31f78023dc453cb85d8e6b8c13614dd2657f8098132118caebdfa'::TEXT, ARRAY[1253]::BIGINT[]),
    (302::BIGINT, 'El curso NO lo regala. No me pareció dificil pero si hay que ser ordenado y llevar todo al dia, se aprende mucho, deja quices cada como 2 semanas con la oportunidad de eximirse del examen final si le va bien en estos. Por halloween regaló un quiz al mejor disfraz, él en sí ayuda mucho como profe.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2022-07-02T00:00:00+00:00'::TIMESTAMPTZ, 'abecb29c2ae27a31ccc8cb10cf8bd8b81186649d1da61f32f3549880e76bae44'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'No lo recomiendo, si va a llevar un curso de programación con el es mejor invertir en un curso de paga porque por lo menos si va a ser difícil va a poder conseguir un título por ello y no solo un pinche curso de carrera que muchas veces ni sirve en la misma carrera'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '947551c69a63365b4f5c7de9416f9c6d568e1c2b73b1a64c3f8190d9bec2f5fa'::TEXT, ARRAY[1184]::BIGINT[]),
    (302::BIGINT, '(VIRTUAL) Profesor recomendado, debe ser autodidacta OBLIGATORIAMENTE, esta condición es para poder pasar el curso fácilmente. De las 4 horas semanales solo da 1 de clase. Deja tareas semanales y 2 proyectos grandes a los que hay que dedicarles más de 20 horas si se quiere entregar algo decente.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Pocos exámenes', 'Deja trabajos largos']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'bc5c846c7ab148d6123bed0d910fdf9c61bccc971e0531526585206dc9a9dd85'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Programar en si es un proceso muy autodidacta, pero el profe explica las bases de la programacion bastante superficialmente, apenas para entender lo que hacen las funciones en python. Las tareas si son un poco complicadas. Pero no me parece mal profe.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'f2189f489577c90c7eec921d97d12e5375aac95b71120857e0aa7b215f208096'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Las clases son cortas, el profesor explica la parte teórica pero el curso es super autodidactica, por lo que hay que invertirle demasiado tiempo extra. Deja trabajos bisemanales y proyectos muy extensos. No lo recomiendo para nada en especial si no conoce nada de programación.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2022-02-01T00:00:00+00:00'::TIMESTAMPTZ, '554ef52e05412a7d133f604176dab342c0aef595202afb5255f019b1be0d38fe'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Muy buena persona. El profe no se mide con la dificultad de los trabajos. Hay que ser completamente autodidacta, hay muy poca información de los programas que pide. Da puntos extra para pasar, pero hay que aprovechar consulta para salir bien y eximirse. Bastante dificil si no se quiere esforza.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2022-01-20T00:00:00+00:00'::TIMESTAMPTZ, 'e42c3c8a44d66414fc7d94c20f5529557d0ae0fccfec36ebea06ed1551dc5ae3'::TEXT, ARRAY[1253]::BIGINT[]),
    (302::BIGINT, 'Las clases son cortas y solo se ve la teoría. A mi criterio el profesor no explica bien, solo lee las diapositivas y no profundiza, a parte que da las clases como con sueño. En lo practico toca ser totalmente autodidacta. A diferencia de otros profesores, no deja tantos trabajos.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-17T00:00:00+00:00'::TIMESTAMPTZ, '389a8e7acb74d9cf904b002bab87ffc01adf49f7e8c7d5c73f53be4d09aa5e31'::TEXT, ARRAY[1253]::BIGINT[]),
    (302::BIGINT, 'El curso es complicado por si mismo, el profe explica la parte teórica y la parte práctica de programación es totalmente autodidacta, pero el profe es buena persona y ayuda bastante en no recargar con muchos trabajos y da muchos trabajos extras para reponer. No falten a las clases son rápidas.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'a0afc18eea2fe37f28423b911c41f480d2905018088ce2e945ba3c96ee943cdd'::TEXT, ARRAY[1253]::BIGINT[]),
    (302::BIGINT, 'Virtual. El profesor es muy consciente de lo que es ser estudiante en el TEC, sus clases son cortas y a veces puede parecer que los temas son muy complicados con su explicación. Las tareas, quices y proyectos son algo dificiles, hagan lo posible para eximirse. El profe ayuda mucho, vayan a consulta.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2021-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'c09730e88bf410b11cae083d8f2b6d087805493f85fdfb5b9d5fea3b40240e99'::TEXT, ARRAY[1253]::BIGINT[]),
    (302::BIGINT, '(Virtual) Se preocupa por el tiempo de los estudiantes, sus tareas y proyectos son algo más complicado de lo normal para el curso pero él da mucho tiempo para su realización, sus clases son muy cortas y van al punto. Se requiere ser muy autodidacta en ocasiones. Con él se aprende mucho.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2021-07-29T00:00:00+00:00'::TIMESTAMPTZ, 'ea1fdedebfc6f813b4956228ba6f47fa05454dffa8fc2427d25e7d9154c830be'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'El profe no es el más simpático pero no es mala gente, no explica muy bien pero si se le entiende y con los ejemplo que hace en clase y videos en YT pasa. Las evaluaciones son fáciles al inicio, solo hay un examen y uno se puede eximir, los proyectos son diferentes pero entretenidos.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '761688e9c4da4dc923a804409d858255c1e4506a543ebb5e14c05fccc73b72bb'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Las clases son de menos de media hora, donde lee unas diapositivas y da el tema por explicado. No da ejemplos de código diciendo que en Internet hay muchos ya hechos. Deja muchísimas tareas extra que le ayudan a uno, hágalas. Si uno se saca más de 80 en los quices se exime del examen final.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2021-07-16T00:00:00+00:00'::TIMESTAMPTZ, '4960c94d07cbe8da31d254843134eded2684d5a48759c5aee1604db889ff2707'::TEXT, ARRAY[1253]::BIGINT[]),
    (302::BIGINT, 'Se aprende demasiado, te ayuda si se muestra interés en la clase. La materia es difícil y las tareas son largas, hay tomarse el tiempo para realizarlas. Da varias tareas extra que son una salvadota.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-07-05T00:00:00+00:00'::TIMESTAMPTZ, '08de219dd0223d3fae015b8e6a67f28adb404c2a94d1c1df9b5d8ae485ce7f0c'::TEXT, ARRAY[1253]::BIGINT[]),
    (302::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'edaa0e81c94f64f2e6926f9b3532d62f107be981f409716ef66e6d195ee1ed3b'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Las clases duran 20 minutos donde explica lo más básico de los temas, y con eso tiene que hacer quices de dificultades variadas. Hay que ser un poco autodidacta. Los proyectos también son de dificultad variada. Pese a todo eso, con él se aprende mucho'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '843982c9a384c024d79ed03b0db4b0e421d6309098797ae966592f62c47dcd95'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Se aprende mucho, pero se sufre todavía más. Explica solo las bases y no da ejemplos de código. Hay que ser autodidacta hasta el punto que pide cosas que no enseña. Los trabajos que pide son desmedidos e incluyen interfaces y conceptos no vistos. No lo recomiendo a menos que sepa programar muy bien'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2021-06-08T00:00:00+00:00'::TIMESTAMPTZ, '0dd4655f361945d244554be8f54f3abbb1f658c99e74739ed97e85bc173aacce'::TEXT, ARRAY[1253]::BIGINT[]),
    (302::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-02-17T00:00:00+00:00'::TIMESTAMPTZ, '1ec566e266a881b90b5ead4d1d91d55f41476af2319c97e54a735abc8ff474ff'::TEXT, ARRAY[1184]::BIGINT[]),
    (302::BIGINT, 'Si usted no tiene principios de programación claros, matricule con él y otras dos materias, si no se va quedar. Va necesitar practicar mucho. De todos los que dan el curso, es con quien más se aprende, porque fomenta mucho la investigación.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2020-12-18T00:00:00+00:00'::TIMESTAMPTZ, '4e6e3b58432c95dbf4f74d4bc97e55347d92ad3ad5a1f120c3a13e9f0c24f9f5'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'En clase solo explica la teoría, asigna proyectos y quices demasiado largos y difíciles para los 3créditos, ocupa 6 horas al día. NO explica como usar C++ e interfaz, es dificil y hay que ser demasiado autodidacta. No matricule a menos que sea la última opción Un tercio del grupo abandonó el curso'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2020-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'f5a91f3612786b26be39f01291bf84504a294348fb756a1a8c06615724b77017'::TEXT, ARRAY[1253]::BIGINT[]),
    (302::BIGINT, 'Es lo mejor para alguien que ya esta repitiendo el curso, si lo llevan por primera vez... Tienen que ponerle mucho, lo difícil no es aprender la teoría de programar, el enseña a pensar... Si el ve interés, lo va a ayudar Hay q hacer TODAS las tareas, eso lo salva a uno.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Da crédito extra']::TEXT[], '2020-11-04T00:00:00+00:00'::TIMESTAMPTZ, 'eaff8e7df4cab52d34fe97b951bdaeb257a6a06f0b9e14a99e590593d96c7211'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Explica lo básico y deja tareas/trabajos/proyectos muy avanzados para lo que se ve en clase. Se hace el empático pero no lo es, hace chistes y regaña duro, a veces hasta humilla.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Pocos exámenes', 'Exámenes retadores']::TEXT[], '2020-11-03T00:00:00+00:00'::TIMESTAMPTZ, '5005cb58014f24f34b134e4eef1a7a993f8890de700bd05c6341539b2d5fc342'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Lamentablemente solo el da el curso, pero es muy malo, juega de que es muy tuanis y que todo es fácil pero siempre los exámenes son rudisimos y nunca explica nada, da una clase súper básica de cada tema y el resto le toca a usted, si no tiene amigos que le ayuden en Progra le va costar un montón'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2020-09-08T00:00:00+00:00'::TIMESTAMPTZ, '002e317f350b7dcf38da39d4b55652372072e507f97dbb146150d755768cc2d8'::TEXT, ARRAY[1022]::BIGINT[]),
    (302::BIGINT, 'Chistes o comentarios sarcásticos (no se los tome a pecho que él no busca ofender), trabajos duros (pero no imposibles, solo busca explotar al máximo la capacidad de cada uno), da los conceptos básicos en clases y posibles dudas y problemas, profundizar ya es su responsabilidad, aprendizaje garantiz'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'La participación importa', 'Da crédito extra']::TEXT[], '2020-09-03T00:00:00+00:00'::TIMESTAMPTZ, '3d56311fa548471c371465c0fe9e424e33a5007ce19b2ecebee5b28c0f8b5fb3'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, '809da358cae7fef4a71e984ddc34d55f573357c39b045fe2a9838c784516939f'::TEXT, ARRAY[1184]::BIGINT[]),
    (302::BIGINT, 'Pesimo profe'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '90840d1d0b26172a907ac3e0ba1b241a2b5dd8ec781ef77c238bcde267a5abd6'::TEXT, ARRAY[1253]::BIGINT[]),
    (302::BIGINT, 'Es un excelente profesor, es Muy buena gente y se preocupa porque la gente entiendo aunque a veces hace comentarios sarcástico un poco groseros. El mae le enseña mucho a uno perl hay que ponerle demasiado al curso porque cualquier evaluación que deja el profe es demasiado difícil.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'baa28b32999b2cca8f5ef81e7e11bc0e97d898b903eccd7f5ff324511bdb6dd6'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, '59532a64a9156ead84ab64a872ed4abc3bf28527e37accc98f00742083b0e1e3'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'f30c2e3c4017d1ece52d68b7f1770f6d8e51eb5f241be21db814780246c8aca1'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '29ef9818a8858b104a82fc6dc5979de34f33d8909a143b3933e1c912b17ce73c'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'El curso se las da, el profe es bueno explicando lo teorico y conceptos de la materia, de ahi en fuera usted tiene que hacer su parte, si le pone al curso va a aprender bastante, las progras son duras pero de todas se aprende algo y se sacan puntos, si le cuadra aprender meta con el'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'd6a5eea86ea577d1deb7012cdc410fda8c41cfdabc7b5cd8654967b745204744'::TEXT, ARRAY[1253]::BIGINT[]),
    (302::BIGINT, 'Excelente profesor, hay que ponerle mucho al curso porque las evaluaciones son rudas. Le interesa mucho que los estudiantes aprendan bien pero uno si tiene que poner bastante de su parte. Da puntos extras en las evaluaciones si uno se los gana. (virtual)'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '7abb66f3ecfbbac560180afc409c3041494b7a0bc351a47d9dc26569caa208ff'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'No se tomen nada de lo que dice a pecho porque en ocasiones los puede hacer sentir inferiores sin embargo durante la pandemia demostró ser el profesor con mayor empatía hacia los estudiantes, van a tener que estudiar mucho por fuera porque simula una vida ya laboral NO DEJEN BOTADO EL CURSO'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'cc0ab17e7caa6977d33706416b7996d5fdf03b564e3f3c5cc8b1f2dab3c36a78'::TEXT, ARRAY[1253]::BIGINT[]),
    (302::BIGINT, 'Es un profe duro pero te obliga a aprender y eso hace el curso muy retroalimentativo, se aprende mucho y aunque sea duro reconoce el trabajo que se hace y lo califica bien.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '1bccf914fda1efacbb79950a97ba6dbdbe24596cc2b524179fd959b8ca323f61'::TEXT, ARRAY[1253]::BIGINT[]),
    (302::BIGINT, 'Es un profesor muy arrogante, durante las clases casi no explica, da ejemplos sencillos, pero en el examen es otra cosa. Para constru sólo él da el curso, por lo que recomiendo se preparen con anticipación viendo tutoriales. Las tareas y quices no son muy complejos, pero proyectos y exámenes sí.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, '0e779759c13c1ca86f6b58862dd42cdef5a6615173e0b228c1b14e1d83108c58'::TEXT, ARRAY[1185, 1184, 3817, 2852]::BIGINT[]),
    (302::BIGINT, 'Pésimo profesor si uno no es un genio programando. Es muy exigente y le gusta jugar de superior y muy "solidario" con los estudiantes, cuando no lo es.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '8c713c825fccf0c90e8b6b19059df1b37c202289c198b46192f82adfa554abd8'::TEXT, ARRAY[1253]::BIGINT[]),
    (302::BIGINT, 'El peor profesor con el que me he topado durante el TEC, no conoce la amabilidad y cuidado con lo que dices en clase porque se toma bastante tiempo en dejarte en mal, se cree bastante superior. Es el único que da el curso así que empiece con los vídeos en YouTube desde semana 1 o antes.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, 'b9332522e1db5660c6604a9eb4679393f4a82240012cd1c1878974012c45daa5'::TEXT, ARRAY[1185, 1184, 3817, 2852]::BIGINT[]),
    (302::BIGINT, 'El peor profesor, se aprende nada y además como persona es un completo arrogante. Tiene preferencias y se cree mejor que los demás, cero empático. Dice que sus títulos y su carrera profesional hablan por él, pero no, es un asco de persona total. Es el único que da el curso, sad.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2020-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'a44936a15a84101bce39e5519a96a3db1cf61c4faa2ca15a58f1bbc60f3f80c3'::TEXT, ARRAY[1185, 1184, 3817, 2852]::BIGINT[]),
    (302::BIGINT, 'Juega demasiado de vivo, le gusta hacer sentir a sus estudiantes completamente inferiores a el, si le preguntas algo en clase de humilla. Sus examenes y proyectos si acaso se relacionan con lo visto en clase, en mi oponion es un pesimo profesor. El curso es un curso facil, pero con él no.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2020-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'b1e842b4d81484dea347188bbb0d7bd138e1fd9e865617e825f0c8f032f56d50'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Un curso de BASTANTE dedicación, recomiendo ir a consulta y tutorias. El profe es buena nota, algo ironico, siempre deja trabajos con una dificultadad media. No comentan el error de dejar botado el curso, deja tareas extras que ayudan a subir la nota pero el MAXIMO esfuerzo siempre sera necesario'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación']::TEXT[], '2020-02-03T00:00:00+00:00'::TIMESTAMPTZ, '5f89ff7111841f8a84e62d90ee79c0f8e3bfb42927437fcf290c23503e387a13'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Me parece que el profesor puede mejorar, debería de explicar mejor la materia y los exámenes son muy difíciles, pero el curso no es tan difícil de pasar, hay que esforzarse en los exámenes, hacer todas las tareas y quices y ya'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2019-12-09T00:00:00+00:00'::TIMESTAMPTZ, 'af4efeb3ba57d3be609d0ff14c0365983f19381e20c45e2ae330c5d6420ce6d0'::TEXT, ARRAY[1184]::BIGINT[]),
    (302::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2019-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'b1b75428b7771d7b539c2c911c36abf7510145cae4a9382da2abbddd27e8ee7f'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Si usted quiere empezar a aprender a programar y a como ser un ingeniero, tiene que matricular con él. Los examenes son rudos, pero no se ahueve. No deje el curso botado, llegue hasta el final. Un profesor difícil, pero sin duda de los mejores que se va a encontrar en el TEC.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Exámenes retadores']::TEXT[], '2019-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'e011959d6652c60746d8ac1cc24b51fd75de329f08b659f896c6a164a0814f1e'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'APRENDI DEMASIADO. Sus examenes van a andar por notas de 40, evalúa demasiado duro, deja mucho asignación extra que ayuda demasiado, no deje botado el curso (ud lo empieza a salvar cuando ya se fue la mitad de la gente), pone problemas que lo ponen a pensar hasta en la ducha. Se nota el nivel.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Inspirador', 'Exámenes retadores']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, '2af510fda502602a3ec6acb04344947d4a58252d0c05c83eb78c89bc5daeb49e'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Hace el curso mucho mas dificil de lo que deberia ser, califica de manera muy estricta. Si usted va a clases, hace los bretes y va a consulta, el profe lo va a ayudar, ademas de que da tareas y quices extra durante el curso. Si se aprueba, es porque usted de verdad aprendio.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2019-11-23T00:00:00+00:00'::TIMESTAMPTZ, '7e8fe50fda4a377b93a528e9c2ebddedb1cf23ab9dc8af3f21635720c4ad665c'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'El más difícil, pero con el que más se aprende'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2019-07-23T00:00:00+00:00'::TIMESTAMPTZ, '3fbbec4a1f3ed15e98ea1af72daabd8dac671917f19c53f8cd811949ca07ce10'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Es un buen profe, ayuda a todo el que está dispuesto a aprender, es un excelente profe, estaría dispuesto a llevar con él hasta Algoritmos'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-07-23T00:00:00+00:00'::TIMESTAMPTZ, '033a43fcaee42fd6a91efc1d9b239147104c6a07cdc1af59e0b8822a7a754cc0'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'El profe en si tiene una muy buen personalidad el mae da consejos y hace bromas, regala un monton de puntos extra pero hay que esforzarse mucho Si usted hace todos los trabajos y lleva todo al dia pasa, aunque lleve notas muy bajas en los examenes si el ve que usted trabajo lo ayuda mucho'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-25T00:00:00+00:00'::TIMESTAMPTZ, '3c4e9ae6a646d47ad3cb0d2c4d5de2ba579d4895202b0c3c61e6a80c88367a99'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Si usted quiere aprender, póngala con este profe. No va a ser fácil, pero vale la pena. Hay que demostrar el interés, él ayuda mucho y da MUCHOS puntos extra. Con él usted si se va a sentir verdaderamente ingenieril, va a hacer algo y ver los resultados. Yo hice un juego...'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '0ea0ab7d5c2726ac2ed4092422637261795d91c1e0b56618d03761fb70b25c07'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Hay que practicar mucho pero siempre brinda apoyo dentro y fuera de clase. Explica la cantidad de veces necesarias y toma mucho en cuenta el interés y esfuerzo que uno le meta al curso.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Deja trabajos largos']::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'b13ca11b81f915670cab308c1d5f9c471713aa5693330bf77000bd1f6a1dc911'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Explica muy bien y muy claro, sabe de lo que habla, se preocupa de que uno entienda los temas Evalúa difícil, los proyectos no son fáciles Si le pone desde el inicio a punta de tareas y quices se pasa Deja tareas y puntos extra que son una salvada'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-06-19T00:00:00+00:00'::TIMESTAMPTZ, '08bbf02f9e1a92e96f7f40481da41ce594af10b8cc2bdb72df2c85b7232e90f2'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'es una excelente persona, ayuda bastante con puntos extra A pesar de que los exámenes y los quices son difíciles, si uno hace las tareas y le pone al curso lo pasa'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, '6372be89115163459234f2857d23bf8840d532d4a59589bc02a5c96ae29f8bf5'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Como persona es excelente, como profe si es muy difícil, pero si uno va a consulta le ayuda además deja muchos puntos extra. Los quices son difíciles y los proyectos complicados pero si se aprende bastante.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2019-04-10T00:00:00+00:00'::TIMESTAMPTZ, 'a93ebad6becf14ddeec9aac7a83f2ab24e61db99d5f1c0ab7e00013de55a178f'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'La materia no la explica lo suficiente y los proyectos y tareas se tienen que hacer empíricamente; pero si muestra interés y se asiste a las horas de consulta aclara todas las dudas hasta que uno entienda. Buena nota.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2019-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'c9ead299f5ee3e7ad70eacebfdb71ad0fe072bd4b36a35a33cfd0cac4adfb10c'::TEXT, ARRAY[1185, 1184, 3817, 2852]::BIGINT[]),
    (302::BIGINT, 'Se aprende mucho pero hay que ser autodidacta muchas veces para lograr llevar al día el curso. Tiene que ponerle desde el principio si quiere pasar.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, '1d96d2929b0a9bd84b5787825df9718da42c1d3a821ace2c754048559ec74c8b'::TEXT, ARRAY[1185, 1184, 3817, 2852]::BIGINT[]),
    (302::BIGINT, 'Es una teja como persona pero como profe es un poco complicado. Hay que ser autodidacta, en clase casi no se aprende nada.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-27T00:00:00+00:00'::TIMESTAMPTZ, '444ddff1a45b3254158c6c4f189ea0949c1cfe4643a56a06f66caf1ae29f5292'::TEXT, ARRAY[1022]::BIGINT[]),
    (302::BIGINT, 'Llévelo con él si quiere aprender y pasarla bien, sinceramente él hizo que mi semestre no fuera tan aburrido'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-07-01T00:00:00+00:00'::TIMESTAMPTZ, '1761f0af783cf657588e4e399f14180c72d4a270b47f57974310643f8a8f4823'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Los exámenes son demasiado difíciles para lo que él explica en clase, aparte que los problemas que vienen suelen ser confusos y pretende que uno los entienda fácilmente. Es arrogante. Ciertos quices son fáciles pero otros no. Si su carrera no necesita sobre programaciones mejor llévelo con otro.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'e76b3444b4ae52b79aafd9df9ccb205cda7fb2557dd1a0fb55f11647e8fb0435'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Sí lo recomiendo, el curso es pasable con él, no falte a clase, haga todas las tareas, califica duro los exámenes pero es cuestión de practicar bien, da puntos extra, se aprende mucho con él, porque a él le importa eso.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '33a10a312eac780ad022e8cbfa11e4b1962d3f182e1309baf0cb35c7f2da547e'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Si lo recomiendo, es super facil pasar si usted va a clases y hace todas las tareas pasa aunque no sepa como hacerlas o las haga mal presentelas, da muchos puntos extras, las clases son divertidas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '4192e6fce0aed2ec3b0fcae0d87c6e3917bd1781f562c58194cbdba5c7125017'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'El profe es excelente, le enseña a uno a ser dedicado y valorar el curso y sin duda es con quien más se aprende. El curso no es sencillo y él exige compromiso, pero ayuda mucho. Recomendado.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'a936284a367895d58a5251d31934febe2604cdc9c741e0bab4a8f4ec748c30a5'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Si le pone con este profe se aprende muchisimo y lo prepara bien si tiene que llevar mas cursos de programacion pero es MUY DURO. El profe es muy tuanis pero hay que dedicarle tiempo y ponerle, no es nada facil'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '91dfe54245075920bd3cca70f5840b3a5edc4fbabfbc7ec443d85b4f10643ee4'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'se puede pasar, pero no es nada fácil, el te obliga a investigar y andarle adelante siempre, estar preparado para cosas que uno ni imagina, pero la verdad si ayuda bastante..... pero de todos el curso de Elementos de él es el MÁS DIFÍCIL'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '24bc979fec1fdcbd2a2765b16f98036ec2fc059dcdc2a30c39ae9b61992afbc0'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'El curso es pasable pero hay que ponerle bastante'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2018-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'b2692872d9c6a8ed661e4f425c7c793692468132701103a5065710a94900e697'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'el curso lo hace mucho más complicado que otros profes, como persona es un 10, como profe un tanto complicado, tareas y proyectos muy duros, hay que ser autodidacta ya que en clase no se aprende casi nada, sin embargo se aprende, meter con él significa parirla'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-31T00:00:00+00:00'::TIMESTAMPTZ, '1e113d2560a769f0419ffb23ed729992fdd74ad6f08fcc359b5aecb5105b0aa6'::TEXT, ARRAY[1022]::BIGINT[]),
    (302::BIGINT, 'Recomiendo al profe para aquellas personas que quieren aprender, los exámenes son muy difíciles, pero si es un curso pasable.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2018-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'c81c91d6c11bd75e89bd11f6142ec16a62f79384c353804cc1d7b672d602b841'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'La verdad es que uno pasa gracias a los puntos extra que da el profe, el mae no explica para nada claro las cosas, los examenes son una mamada, pero por lo menos el profe es buena nota'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-28T00:00:00+00:00'::TIMESTAMPTZ, '57ea8b784d4834f48e8d81766a97537649ca118450ec76cc253333993b8a7cc0'::TEXT, ARRAY[1185, 1184, 3817, 2852]::BIGINT[]),
    (302::BIGINT, 'La verdad habia scuchado malos comentarios de él y cuando comenzó el semestre imaginaba lo peor, pero todo fue cambiando, se aprende bastante porque sus tareaas y proyectos amritan ponerle mucho, es agradable. Sus examenes si son rudos, pero el curso se puede pasar, solo requiere constancia'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-09T00:00:00+00:00'::TIMESTAMPTZ, '8b1535a0a5f5523a24fd257c54c221892b3cb5ec5348cef46f83cdc5f12b069b'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Se aprende mucho pero no porque él ayude sino porque demanda ser autodidacta, él evalúa muy duro, sus exámenes y proyectos son para matar al estudiante, a veces no le gusta ayudar y es un poco infantil con todo, sus clases son de 20 minutos y el resto es perder el tiempo.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-07-26T00:00:00+00:00'::TIMESTAMPTZ, 'c1da83fffd7603a08e3f5676c75460d8e1bc3cb3b212de2108bbf3c64afc193e'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Es un excelente profe, uno realmente aprende, no es para personas mediocres que buscan pasar un curso fácil, hay que ponerle y dedicarle tiempo, el profe es excelente persona y explica cuantas veces sea necesario'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '89c538f776ad273f1c2e0f90cd7941c4d0b9e112fbd447142aa04009ca0ce674'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'El profe es un poco juega de vivo. en la calse se ven cosas muy básicas, y tenés que ser autodidacta. muchas cosas las tenés que investigar para hacer los proyectos. el profe como persona es tuanis, pero si no le ponés al curso no lo pasás.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Deja trabajos largos']::TEXT[], '2017-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1f947e1576a8b6ba3bbb95a7d89ecc986afdc0ba8b54b777f590c325480b8618'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2017-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'd0fc01dd66117f97018b5134792418c93c317ea23f4bf2c1212c6638e210e43f'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'NO MATRICULE CON ESTE PROFE... SE VA A ARREPENTIR!. no explica nada nunca termina las clases, se va temprano y suele llegar tarde. Después de matricular con el va a desear retirar la materia. Le gusta humillar a los estudiantes.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'feec49b4e1aec6b90ac3b2abd94f17765ecff533954c0b2d39d966afeba1d026'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Da bastante porcentaje extra en el curso, sin embargo explica mal y casi no se le entiende la verdad, no hay otra opción, meta con un grupo de amigos para realizar todo en grupo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2017-06-04T00:00:00+00:00'::TIMESTAMPTZ, '4d10cfa4ec9eb2c12fea25b2e0a4b545125f73810c39181f50984f80eeaf4fe5'::TEXT, ARRAY[1185, 1184, 3817, 2852]::BIGINT[]),
    (302::BIGINT, 'Nunca matriculen con el, los proyectos son voladisimos y los quices y examenes tambien, el trata de ayudar, pero lo que explica no se entiende y en los quices y ejercicios hace como si usted llevara años de programar.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2017-03-17T00:00:00+00:00'::TIMESTAMPTZ, '8c98741223fcedc25358ceb55f828541a110385428d1abb1212644760549b81e'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Sus exámenes son completamente diferentes a todo lo que uno ve en clase y no explica bien la materia porque da muy pocos ejemplos.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'ec4700ef089d273d0aaa4f6cdd818505ebe8998b910e986b8be38b49f6343d8d'::TEXT, ARRAY[1184]::BIGINT[]),
    (302::BIGINT, 'Explica bien y se preocupa por que uno entienda, pero los exámenes son muy volados y los quices son intermedios.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-02T00:00:00+00:00'::TIMESTAMPTZ, '9df56c0b738c0ce41414da448ffdc02045670771e11ae36e8fefd9fb0fcf764f'::TEXT, ARRAY[1184]::BIGINT[]),
    (302::BIGINT, 'Prepárese para ser autodidacta. El profe TRATA de explicar los temas de forma clara, si usted no entiende él explica de nuevo. Quices, en su mayoría, difíciles, tareas muy fáciles. Los proyectos es nada más de sacar su tiempo y dedicación. Los exámenes son regulares. El profe califica suave.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'd2fe9cbaf2df7b4531081157c819e7c70f148019a9266a55bf9a3abc478f8a43'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'No me pareció buen profesor. Pretende que los alumnos entiendan las cosas casi que solos, no sabe explicar, aunque si lo intenta cuando la gente tiene dudas. Califica con compasión y pone preguntas de puntos extra en los examenes, pero deja proyectos voladísimos que cuesta demasiado sacar'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, '416881218b33612d13ac3cf8dc359c6f3920ac86be481ffe64913481f59fcaf1'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Es un profe buena gente, el mae siempre explica bien y si alguno no entendio algun tema se devuelve a explicar, las tareas son faciles y para los examenes aparte de que da bastantes puntos extra, da suficiente tiempo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-08T00:00:00+00:00'::TIMESTAMPTZ, '5378f19b88f464726f6f30fe0d5b57cd65f1559f5062f370a94c994e4310f8c4'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Mal profesor, sus quices, examenes y proyectos nunca van acorde con la materia vista en clase, aparte que nunca explica nada, todo lo que aprendi del curso lo aprendi en Youtube'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2016-05-18T00:00:00+00:00'::TIMESTAMPTZ, 'e9381a5cd339a72ff7465fead697b88c5b7afc0dd5a761785e5265bebd9a3093'::TEXT, ARRAY[1249]::BIGINT[]),
    (302::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-07T00:00:00+00:00'::TIMESTAMPTZ, 'b517a931bf8fcaf1d82aeaf4042e858a18696ed6493028b2308b56d8e40dbb0d'::TEXT, ARRAY[1029]::BIGINT[]),
    (302::BIGINT, 'La peor experiencia que he tenido en el TEC. No merece ser llamado profesor. Las mayoría de "clases" son una pérdida de tiempo. "Explicaciones" improvisadas. Hace todo un drama por cuestiones sin importancia. No se aprende nada útil de parte de él. Pésimo es un halago. Acosa a los estudiantes.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-07T00:00:00+00:00'::TIMESTAMPTZ, '0ad16523cb627c0f76fc877def7dfde283e2b92e65830dd2a6080d850f7f225b'::TEXT, ARRAY[1039]::BIGINT[]),
    (302::BIGINT, 'Yo no se quien le dijo a este mae que podía ser profesor, sinceramente no tiene ni lo minimo que requiere, el mae no explica nada, se basa en el libro que tiene en el telefono y eso es todo, no aclara las dudas, no es puntual, solo sabe hacer quices (del libro que ni el sabe q dice).'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-12-02T00:00:00+00:00'::TIMESTAMPTZ, '1c2e10744130363ae594837471ddc034ea72fe7f7f64eea0d70d5732c57ab6ab'::TEXT, ARRAY[1039]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
